//! Demotion signals: generated, test, bundled and vendored paths, generated
//! file headers, and `.gitattributes` `linguist-*` marks.

use crate::text::test_paths::is_test_path;

/// Directory names of generated files, which rank after every hand-written
/// file whatever their match count.
const GENERATED_DIRECTORIES: &[&str] = &["generated", "__generated__"];

/// File-name fragments of generated files.
const GENERATED_FILE_MARKERS: &[&str] = &[".generated.", "_generated.", ".pb.", "_pb2."];

/// Directory names of bundled and vendored files, which (with generated
/// ones) rank after source files; test directories are [`is_test_path`]'s.
const BUNDLED_DIRECTORIES: &[&str] = &["dist", "build", "vendor", "third_party"];

/// File-name fragments of minified bundles: demoted, not generated.
const MINIFIED_FILE_MARKERS: &[&str] = &[".min."];

/// Leading bytes read for a generated-file header.
pub(crate) const GENERATED_HEADER_BYTES: u64 = 512;

/// Header phrases of generated files (`Code generated by … DO NOT EDIT.`,
/// `@generated`, `Automatically generated by …, do not edit.`), compared
/// case-insensitively.
const GENERATED_HEADER_MARKERS: &[&str] = &[
    "do not edit",
    "@generated",
    "code generated",
    "automatically generated",
    "auto-generated",
    "autogenerated",
];

/// Whether a root-relative path names a generated file by its directory or
/// name. Only the path below the search root is judged.
pub(crate) fn is_generated_path(relative: &str) -> bool {
    path_names(
        relative,
        &[GENERATED_DIRECTORIES],
        &[GENERATED_FILE_MARKERS],
    )
}

/// Whether a root-relative path has a directory in one of `directories` or
/// a file name holding one of `markers` (ASCII case-insensitive, either
/// separator).
fn path_names(relative: &str, directories: &[&[&str]], markers: &[&[&str]]) -> bool {
    let lower: String = relative
        .chars()
        .map(|c| {
            if c == '\\' {
                '/'
            } else {
                c.to_ascii_lowercase()
            }
        })
        .collect();
    let mut parts = lower.rsplit('/');
    let name = parts.next().unwrap_or_default();
    parts.any(|dir| directories.iter().any(|names| names.contains(&dir)))
        || markers
            .iter()
            .flat_map(|names| names.iter())
            .any(|marker| name.contains(marker))
}

/// Whether a file's leading bytes declare it generated: a marker phrase in
/// its first lines.
pub(crate) fn has_generated_header(prefix: &[u8]) -> bool {
    let head = String::from_utf8_lossy(prefix).to_ascii_lowercase();
    head.lines().take(5).any(|line| {
        GENERATED_HEADER_MARKERS
            .iter()
            .any(|marker| line.contains(marker))
    })
}

/// Whether a root-relative path is a test, fixture, generated, bundled, or
/// vendored file. Only the path below the search root is judged, so searching
/// inside `tests/` itself does not demote every result.
pub(crate) fn is_demoted_path(relative: &str) -> bool {
    is_test_path(relative)
        || path_names(
            relative,
            &[GENERATED_DIRECTORIES, BUNDLED_DIRECTORIES],
            &[GENERATED_FILE_MARKERS, MINIFIED_FILE_MARKERS],
        )
}

/// `.gitattributes` `linguist-generated` / `linguist-vendored` marks, as git
/// resolves them: the deepest attributes file decides, its last matching line
/// wins, and `-attr`, `!attr` or `attr=false` unset. Read once per directory
/// per search; only inside a repository ([`crate::search::repository`]): a git or a
/// Jujutsu checkout.
pub(crate) struct GitAttributes {
    repo_root: std::path::PathBuf,
    dirs: std::sync::Mutex<
        std::collections::HashMap<std::path::PathBuf, std::sync::Arc<Vec<AttributeRule>>>,
    >,
}

struct AttributeRule {
    pattern: ignore::gitignore::Gitignore,
    generated: bool,
}

const GENERATED_ATTRIBUTES: [&str; 2] = ["linguist-generated", "linguist-vendored"];

impl GitAttributes {
    /// `None` outside a repository ([`crate::search::repository`]).
    pub(crate) fn new(search_root: &std::path::Path) -> Option<Self> {
        let repo_root = crate::search::repository::nearest(search_root)?.to_path_buf();
        Some(Self {
            repo_root,
            dirs: std::sync::Mutex::default(),
        })
    }

    /// Whether the attributes mark `file` generated or vendored.
    pub(crate) fn marks_generated(&self, file: &std::path::Path) -> bool {
        for dir in file.ancestors().skip(1) {
            if !dir.starts_with(&self.repo_root) {
                break;
            }
            let rules = self.rules(dir);
            if let Some(rule) = rules
                .iter()
                .rev()
                .find(|rule| rule.pattern.matched(file, false).is_ignore())
            {
                return rule.generated;
            }
        }
        false
    }

    fn rules(&self, dir: &std::path::Path) -> std::sync::Arc<Vec<AttributeRule>> {
        if let Some(rules) = self
            .dirs
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(dir)
            .cloned()
        {
            return rules;
        }
        let rules = std::sync::Arc::new(
            std::fs::read_to_string(dir.join(".gitattributes"))
                .map(|text| parse_attributes(dir, &text))
                .unwrap_or_default(),
        );
        {
            let mut dirs = self
                .dirs
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            dirs.insert(dir.to_path_buf(), std::sync::Arc::clone(&rules));
        }
        rules
    }
}

/// The lines of one `.gitattributes` that set or unset a generated mark.
fn parse_attributes(dir: &std::path::Path, text: &str) -> Vec<AttributeRule> {
    text.lines()
        .filter_map(|line| {
            let mut tokens = line.split_whitespace();
            let pattern = tokens
                .next()
                .filter(|p| !p.starts_with('#') && !p.starts_with('"'))?;
            let mut generated = None;
            for token in tokens {
                let (unset, attribute) = match token.strip_prefix(['-', '!']) {
                    Some(name) => (true, name),
                    None => (false, token),
                };
                let (name, value) = attribute.split_once('=').unwrap_or((attribute, "true"));
                if GENERATED_ATTRIBUTES.contains(&name) {
                    let set = !unset && value != "false";
                    generated = Some(generated.unwrap_or(false) || set);
                }
            }
            let generated = generated?;
            let mut builder = ignore::gitignore::GitignoreBuilder::new(dir);
            builder.add_line(None, pattern).ok()?;
            Some(AttributeRule {
                pattern: builder.build().ok()?,
                generated,
            })
        })
        .collect()
}
